mapper.select:
SELECT DATE(r.confirmed_at) AS sale_date, COUNT(*) AS ticket_count, SUM(r.amount) AS total_amount FROM reservation r JOIN seat s ON s.id = r.seat_id JOIN performance_schedule ps ON ps.id = s.schedule_id WHERE r.status = 'CONFIRMED'
AND DATE(r.confirmed_at) >= #{from}
AND DATE(r.confirmed_at) <= #{to}
AND ps.performance_id = #{performanceId}
GROUP BY DATE(r.confirmed_at) ORDER BY sale_date ASC

SELECT p.id AS performance_id, p.title AS title, COUNT(*) AS ticket_count, SUM(r.amount) AS total_amount FROM reservation r JOIN seat s ON s.id = r.seat_id JOIN performance_schedule ps ON ps.id = s.schedule_id JOIN performance p ON p.id = ps.performance_id WHERE r.status = 'CONFIRMED'
AND DATE(r.confirmed_at) >= #{from}
AND DATE(r.confirmed_at) <= #{to}
GROUP BY p.id, p.title ORDER BY total_amount DESC LIMIT #{limit}

SELECT s.grade AS grade, COUNT(*) AS ticket_count, SUM(r.amount) AS total_amount FROM reservation r JOIN seat s ON s.id = r.seat_id JOIN performance_schedule ps ON ps.id = s.schedule_id WHERE r.status = 'CONFIRMED'
AND DATE(r.confirmed_at) >= #{from}
AND DATE(r.confirmed_at) <= #{to}
AND ps.performance_id = #{performanceId}
GROUP BY s.grade ORDER BY s.grade ASC

SELECT SUM(CASE WHEN r.status = 'CONFIRMED' THEN 1 ELSE 0 END) AS confirmed_count,
       SUM(CASE WHEN r.status = 'CANCELED'  THEN 1 ELSE 0 END) AS canceled_count
  FROM reservation r
  JOIN seat s                 ON s.id = r.seat_id
  JOIN performance_schedule ps ON ps.id = s.schedule_id
 WHERE r.status IN ('CONFIRMED', 'CANCELED')

   AND DATE(r.created_at) >= #{from}


   AND DATE(r.created_at) <= #{to}


   AND ps.performance_id = #{performanceId}
